PFX={'NZD':'NZ$','AUD':'A$','USD':'US$'}
def format_money(amount, currency):
    if currency not in PFX: raise ValueError('currency')
    d=r2(Decimal(str(amount)))
    s='-' if d<0 else ''
    return s+PFX[currency]+str(abs(d))

